const rows = $input.first().json;
const doc = Array.isArray(rows) ? rows[0]?.data : rows?.data;
if (!doc) return [];
const telefono = (doc.settings && doc.settings.notifyPhone) || $env.MALONIC_NICO_PHONE;
if (!telefono) return [];
const tz = 'America/Monterrey';
const hoyKey = new Date().toLocaleDateString('sv-SE', { timeZone: tz });
const hace7 = new Date(Date.now() - 7 * 24 * 3600 * 1000).toLocaleDateString('sv-SE', { timeZone: tz });
const semana = (doc.bookings ?? []).filter(b => b.date >= hace7 && b.date <= hoyKey && b.status !== 'cancelled');
const fmt = n => new Intl.NumberFormat('es-MX').format(n);
const facturado = semana.filter(b => b.status === 'confirmed' || b.status === 'completed').reduce((a, b) => a + b.amount, 0);
const horas = semana.reduce((a, b) => a + b.duration, 0);
const completadas = semana.filter(b => b.status === 'completed').length;
const pendientes = (doc.bookings ?? []).filter(b => b.status === 'pending').length;
const balance = b => (b.status === 'cancelled' || b.paymentStatus === 'paid') ? 0 : (b.amount - b.deposit);
const porCobrar = (doc.bookings ?? []).filter(b => (b.status === 'confirmed' || b.status === 'completed')).reduce((a, b) => a + balance(b), 0);
const mensaje = [
  `📊 Semana Malonic (${hace7} → ${hoyKey})`,
  `Sesiones: ${semana.length} (${completadas} completadas) · ${horas}h`,
  `Facturación: $${fmt(facturado)} MXN`,
  `Por cobrar total: $${fmt(porCobrar)} MXN`,
  pendientes > 0 ? `⏳ ${pendientes} reserva(s) sin depósito` : '✅ Sin pendientes de depósito',
  `Detalle: https://malonic-website.vercel.app/admin → Analítica`,
].join('\n');
return [{ json: { mensaje, telefono } }];
